use crate::{model::*,unit_support::*,rules::*,bq047 as b};
fn entered()->(Game,String){let mut g=game();let id=field(&mut g,b::ID,0);g.enter_triggers(0,b::ID,&id,false);g.drive().unwrap();(g,id)}
#[test]fn bq047_original_closed_definition(){let c=crate::catalog::card(b::ID);assert!(!c.supported);assert_eq!(c.cost,4);assert_eq!(c.defense,Some(2));assert_eq!(c.permanent_icons.combat,2);assert_eq!(c.temporary_icons.investigation,1);assert_eq!(c.temporary_icons.influence,1);assert_eq!(b::definition().traits.kill,1);assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();}
#[test]fn bq047_forced_entry_is_respondable_and_destroys_original_region(){let(mut g,id)=entered();assert!(g.pending.is_none());assert_eq!(g.stack.last().unwrap().frame.as_ref().unwrap().ability_key,b::KEY);restore(&mut g);g.regions[0].cards.retain(|c|c.id!=id);crate::jc029_tests::pass_top(&mut g);assert!(g.regions[0].destroyed);restore(&mut g);}
#[test]fn bq047_replaced_region_never_redirects(){let(mut g,_)=entered();g.regions[0].card=g.make_card("DQJC115",0);crate::jc029_tests::pass_top(&mut g);assert!(!g.regions[0].destroyed);restore(&mut g);}
#[test]fn bq047_corrupt_frame_and_duplicate_continuation_rejected(){let(g,_)=entered();for n in 0..4{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.steps.clear(),1=>f.source.source_region_instance=None,2=>f.source.card.definition="JC125".into(),_=>bad.effects.push_back(Effect::Frame{frame:Box::new(f.clone())})}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]fn bq047_real_paid_deploy_room_duplicate_and_restore(){use crate::abi112_review_play_tests::Trace;let mut g=game();fund(&mut g,0,"JC049",4);let id=held(&mut g,b::ID,0);let mut t=Trace::new_preserving_rng(g,"bq047-prepared-paid-deploy".into(),7400);t.action(0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});for _ in 0..32{if t.room.game.pending.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}t.pass();}assert!(t.room.game.regions[0].destroyed);let mut v=t.value();for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}if let Ok(path)=std::env::var("BQ047_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&v).unwrap()).unwrap();}}
#[test]fn bq047_rumor_accept_decline_and_restoration(){for seal in [false,true]{let mut g=game();let host=field(&mut g,"JC125",0);fund(&mut g,0,"JC084",3);let source=held(&mut g,"XG28",0);act(&mut g,0,Action{card_id:Some(source),region:Some(0),..Action::new("play")});crate::jc029_tests::pass_top(&mut g);let source=g.attachments.iter().find(|a|a.card.definition=="XG28").unwrap().card.id.clone();g.players[0].deck=vec![g.make_card(b::ID,0)];g.turn+=1;g.begin_window(Window::Prepare);g.drive().unwrap();choose(&mut g,vec![source]);for _ in 0..32{if g.pending.is_some(){break}pass(&mut g);}assert_eq!(g.pending.as_ref().unwrap().choice.kind,"rumor");restore(&mut g);choose(&mut g,if seal{vec![host.clone()]}else{vec![]});assert_eq!(g.sealed_cards.iter().filter(|s|s.host_id==host&&s.card.definition==b::ID).count(),usize::from(seal));assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition==b::ID).count(),usize::from(!seal));restore(&mut g);}}
#[test]fn bq047_natural_private_deck_entry_export(){use crate::{deck,catalog,abi112_review_play_tests::Trace};fn start(seed:u64)->(Game,deck::DeckDraft){let mut d=deck::preset("watchers").unwrap();d.society_id=None;d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:b::ID.into(),count:3},catalog::DeckEntry{card_id:"JC049".into(),count:3},catalog::DeckEntry{card_id:"JC125".into(),count:44}];let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=d.clone();other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq047".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}let(seed,g,d)=(1..1025).find_map(|seed|{let(g,d)=start(seed);[b::ID,"JC049"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id)).then_some((seed,g,d))}).unwrap();let mut t=Trace::new_preserving_rng(g,"bq047-natural-paid-entry".into(),7401);let mut played=false;for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue}if played&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<4{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==if g.players[0].assets.is_empty(){"JC049"}else{"JC125"})))}else{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(0)&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))};if let Some(a)=a{let a=a.action.clone();played|=a.kind=="deploy";t.action(0,a);}else{t.pass();}}assert!(played&&t.room.game.regions[0].destroyed);let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed);s["duplicate"]=serde_json::to_value(d).unwrap();}if let Ok(p)=std::env::var("BQ047_NATURAL_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}}
fn clock_entry(counts:[usize;4])->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSJZ03",0));for(s,n)in counts.into_iter().enumerate(){fund(&mut g,s,"JC125",n);}let id=field(&mut g,b::ID,0);g.enter_triggers(0,b::ID,&id,false);g.drive().unwrap();crate::jc029_tests::pass_top(&mut g);g}
fn bad(g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let room=crate::room::RoomEnvelope::from_game(g.clone());assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}
#[test]fn bq047_clock_identity_cannot_be_initial_even_with_private_support(){let s=crate::society::definition("MSJZ03").unwrap();assert!(!s.card.supported);assert!(crate::society::validate_construction(s,&[],&[]).is_err());let mut d=crate::deck::preset("watchers").unwrap();d.society_id=Some("MSJZ03".into());let mut ss=crate::catalog::catalog().societies.clone();ss.iter_mut().find(|s|s.card.id=="MSJZ03").unwrap().card.supported=true;assert!(crate::deck::validate_with_registry(d,&crate::catalog::catalog().cards,&ss).is_err());}
#[test]fn bq047_clock_assets_select_four_or_all_and_commit_after_all_players(){let counts=[6,2,0,4];let mut g=clock_entry(counts);let originals=g.players.iter().map(|p|p.assets.iter().map(|c|c.id.clone()).collect::<Vec<_>>()).collect::<Vec<_>>();for s in [0,1,3]{let p=g.pending.clone().unwrap();assert_eq!(p.seat,s);let n=counts[s].min(4);assert_eq!(p.choice.min,Some(n));assert_eq!(p.choice.max,Some(n));for seat in 0..4{assert_eq!(g.players[seat].assets.len(),counts[seat]);}restore(&mut g);let room=crate::jc029_tests::envelope(&g);crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).unwrap();choose(&mut g,originals[s][..n].to_vec());}assert!(g.pending.is_none());for s in 0..4{assert_eq!(g.players[s].assets.len(),counts[s].saturating_sub(4));assert_eq!(g.players[s].graveyard.len(),counts[s].min(4));}restore(&mut g);}
#[test]fn bq047_clock_choice_rejects_wrong_seat_duplicate_forged_receipts_and_pending_replay(){let mut g=clock_entry([5,2,1,0]);let p=g.pending.clone().unwrap();let ids=p.choice.options[..4].iter().map(|o|o.id.clone()).collect::<Vec<_>>();for seat in [1,2]{reject(&mut g,seat,Action{choice_id:Some(p.choice.id.clone()),selected:Some(ids.clone()),..Action::new("choose")});}let mut repeated=ids.clone();repeated[1]=repeated[0].clone();reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(repeated),..Action::new("choose")});for n in 0..5{let mut x=g.clone();match n{0=>x.pending.as_mut().unwrap().seat=1,1=>x.pending.as_mut().unwrap().choice.min=Some(0),2=>if let ChoiceResolution::Frame{frame,..}=&mut x.pending.as_mut().unwrap().resolution{frame.source.card.definition="JC125".into();},3=>if let ChoiceResolution::Frame{frame,..}=&x.pending.as_ref().unwrap().resolution{x.effects.push_back(Effect::Frame{frame:frame.clone()});},_=>if let ChoiceResolution::Frame{choice:FrameChoice::BQ047Assets{chosen},..}=&mut x.pending.as_mut().unwrap().resolution{chosen.push(vec![]);}}bad(&x);}choose(&mut g,ids);reject(&mut g,0,Action{choice_id:Some(p.choice.id),selected:Some(vec![]),..Action::new("choose")});restore(&mut g);}
#[test]fn bq047_clock_checks_personal_society_at_resolution_not_teammate(){for seat in [1,2]{let mut g=game();g.players[seat].society_zone.card=Some(g.make_card("MSJZ03",seat));fund(&mut g,0,"JC125",5);let id=field(&mut g,b::ID,0);g.enter_triggers(0,b::ID,&id,false);g.drive().unwrap();crate::jc029_tests::pass_top(&mut g);assert!(g.pending.is_none());assert_eq!(g.players[0].assets.len(),5);restore(&mut g);}let(mut g,_)=entered();fund(&mut g,0,"JC125",5);g.players[0].society_zone.card=Some(g.make_card("MSJZ03",0));crate::jc029_tests::pass_top(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq047-assets");restore(&mut g);}
#[test]fn bq047_actual_mystic_shown_cost_four_plus_three(){let mut g=game();let cards=[b::ID,"JC125","JC125","JC125"].iter().enumerate().map(|(s,id)|held(&mut g,id,s)).collect::<Vec<_>>();fund(&mut g,0,"JC125",2);let source=held(&mut g,"BQ090",0);act(&mut g,0,Action{card_id:Some(source),ability_id:Some(crate::import20_contest::HAND.into()),..Action::new("activate")});crate::jc029_tests::pass_top(&mut g);for c in cards{assert_eq!(g.pending.as_ref().unwrap().choice.kind,crate::mystic_contest::COMMIT_KIND);restore(&mut g);choose(&mut g,vec![c]);}assert_eq!(g.mystic_history[0].shown[0].value,7);for _ in 0..12{if g.pending.is_some(){choose(&mut g,vec![]);}else{break}}restore(&mut g);}
#[test]fn bq047_clock_zero_assets_and_foreign_owned_asset_destination(){let g=clock_entry([0,0,0,0]);assert!(g.pending.is_none());restore(&mut g.clone());let mut g=clock_entry([1,0,0,0]);let mut c=g.players[0].assets[0].clone();c.owner=2;g.players[0].assets[0]=c;let p=g.pending.as_mut().unwrap();p.choice.options[0].card=None;let id=g.players[0].assets[0].id.clone();/* Refresh only the explicit fixture's public option after establishing foreign ownership. */if let ChoiceResolution::Frame{frame,..}=g.pending.as_ref().unwrap().resolution.clone(){g.pending=None;let mut f=*frame;f.cursor=0;f.guard=GuardState::Unchecked;g.stack.clear();g.effects.clear();g.resolve_frame(f).unwrap();}restore(&mut g);choose(&mut g,vec![id]);assert!(g.players[0].graveyard.is_empty());assert_eq!(g.players[2].graveyard.len(),1);restore(&mut g);}
#[test]fn bq047_nested_rule_transplant_is_rejected(){let mut a=b::definition().abilities.remove(0);a.ops=vec![Op::ForEachLivingPlayer(vec![Op::BQ047Entry])];assert!(crate::rules::validate_ability("JC125",&a).is_err());assert!(b::validate_ability(b::ID,&a).is_err());}
fn duplicate_case(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
#[test]fn bq047_clock_and_scoring_native_export(){use crate::abi112_review_play_tests::Trace;let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSJZ03",0));for(s,n)in [6,2,0,4].into_iter().enumerate(){fund(&mut g,s,"JC049",n);}let id=held(&mut g,b::ID,0);let mut t=Trace::new_preserving_rng(g,"bq047-prepared-clock-paid-entry-assets".into(),7410);t.action(0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});for _ in 0..40{if let Some(p)=t.room.game.pending.clone(){assert_eq!(p.choice.kind,"bq047-assets");t.choose(p.choice.options.iter().take(p.choice.min.unwrap()).map(|o|o.id.clone()).collect());}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}else{t.pass();}}assert_eq!(t.room.game.players.iter().map(|p|p.assets.len()).collect::<Vec<_>>(),vec![2,0,0,0]);let conditional=duplicate_case(t.value());
let mut g=game();let ids=[b::ID,"JC125","JC125","JC125"].iter().enumerate().map(|(s,id)|held(&mut g,id,s)).collect::<Vec<_>>();fund(&mut g,0,"JC125",2);let source=held(&mut g,"BQ090",0);let mut t=Trace::new_preserving_rng(g,"bq047-prepared-real-mystic-seven".into(),7411);t.action(0,Action{card_id:Some(source),ability_id:Some(crate::import20_contest::HAND.into()),..Action::new("activate")});for _ in 0..50{if let Some(p)=t.room.game.pending.clone(){t.choose(if p.choice.kind==crate::mystic_contest::COMMIT_KIND{vec![ids[p.seat].clone()]}else{vec![]});}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty()&&t.room.game.mystic_contest.is_none(){break}else{t.pass();}}assert_eq!(t.room.game.mystic_history[0].shown[0].value,7);let scoring=duplicate_case(t.value());
if let Ok(path)=std::env::var("BQ047_EXTRA_OUT"){use sha2::{Digest,Sha256};let mut bindings=crate::shoggoth_tests::shoggoth_source_bindings();for(n,bytes)in[("rust-game/src/bq047.rs",include_bytes!("bq047.rs").as_slice()),("rust-game/src/bq047_tests.rs",include_bytes!("bq047_tests.rs").as_slice()),("rust-game/src/msjz03.rs",include_bytes!("msjz03.rs").as_slice())]{bindings["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":bindings,"cases":[conditional,scoring]})).unwrap()).unwrap();}}
